'use client';

import { useChat } from '@ai-sdk/react';

export default function ChatComponent() {
  const { messages, input, handleInputChange, handleSubmit } = useChat();

  return (
    <div className="flex flex-col h-full max-w-xl mx-auto p-4">
      <div className="flex-1 overflow-y-auto space-y-4 mb-4">
        {messages.map((m) => (
          <div key={m.id} className={`p-3 rounded-lg ${m.role === 'user' ? 'bg-blue-100 text-right' : 'bg-gray-100'}`}>
            <strong>{m.role === 'user' ? 'You: ' : 'AI: '}</strong>
            {m.content}
          </div>
        ))}
      </div>
      <form onSubmit={handleSubmit} className="flex gap-2">
        <input
          className="border rounded p-2 flex-1"
          value={input}
          onChange={handleInputChange}
          placeholder="Ask anything..."
        />
        <button type="submit" className="bg-blue-600 text-white px-4 py-2 rounded">
          Send
        </button>
      </form>
    </div>
  );
}

import { openai } from '@ai-sdk/openai';
import { streamText } from 'ai';
import { z } from 'zod';

export async function POST(req: Request) {
  const { messages } = await req.json();

  const result = await streamText({
    model: openai('gpt-4o'),
    messages,
    tools: {
      getStockLevel: {
        description: 'Get stock level for a specific item code',
        parameters: z.object({
          itemCode: z.string().describe('The product SKU or item code'),
        }),
        execute: async ({ itemCode }) => {
          // Connect to database and fetch stock
          const stock = await fetchStockFromDB(itemCode);
          return { itemCode, stock };
        },
      },
    },
  });

  return result.toDataStreamResponse();
}
